package com.movieticket.booking; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; class BookingTest {@Test void bookingCapturesOwnerAndSeat(){Booking b=new Booking(7L,"S02","user@example.com");assertEquals(7L,b.getShowId());assertEquals("S02",b.getSeatNumber());assertEquals("user@example.com",b.getEmail());assertEquals("CONFIRMED",b.getStatus());}}